36b7a512a141302eda38e0c01fd22bf743c165d0:
query OverdueReport($first: Int! = 10, $after: String, $history: Int! = 3) {
  overdueLoans(first: $first, after: $after) {
    edges {
      node {
        id
        dueAt
        tool {
          id
          name
          branch {
            name
          }
        }
        member {
          displayName
          email
          loans(first: $history) {
            edges {
              node {
                id
                status
                tool {
                  name
                }
              }
            }
          }
        }
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

678869116fc610c7642dfef83a2a1c0eba2c4706:
query DeskLookup($barcode: String!) {
  tool(by: {barcode: $barcode}) {
    id
    name
    condition
    available
    currentLoan {
      id
      dueAt
      status
      member {
        displayName
        email
      }
    }
  }
}

6b26c38cefa22a20406d375442a7abc976cb0eeb:
query MyLoans($first: Int! = 10, $after: String, $status: LoanStatus) {
  me {
    id
    displayName
    email
    loans(first: $first, after: $after, status: $status) {
      edges {
        node {
          id
          status
          borrowedAt
          dueAt
          returnedAt
          tool {
            id
            name
            branch {
              name
            }
          }
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
}

82c311c6bae369fb89e68ddd44bc441803213816:
mutation ReturnTool($loanId: ID!) {
  returnTool(input: {loanId: $loanId}) {
    __typename
    ... on Returned {
      loan {
        id
        status
        returnedAt
        tool {
          id
          available
        }
      }
    }
    ... on Problem {
      message
    }
  }
}

8d72da6688a5b1e1d2143e92ad0d754c26f8ede1:
subscription Availability($toolId: ID!) {
  availabilityChanged(toolId: $toolId) {
    available
    at
    tool {
      id
    }
  }
}

b88e36992e2db4914c65733c4719449c9062afcd:
query ToolPage($first: Int! = 12, $after: String, $filter: ToolFilter, $sort: ToolSort! = NAME_ASC) {
  tools(first: $first, after: $after, filter: $filter, sort: $sort) {
    totalCount
    edges {
      cursor
      node {
        ...ToolCard
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}
fragment ToolCard on Tool {
  id
  name
  condition
  available
  specs {
    __typename
    summary
  }
  category {
    name
  }
  branch {
    name
  }
}

c655d45d64b7c35a9a093b414d0782dcb5fc51b6:
query ToolDetail($by: ToolLookup!) {
  tool(by: $by) {
    ...ToolCard
    barcode
    addedAt
    branch {
      address
      openingHours
    }
    specs {
      ... on PowerSpecs {
        volts
        cordless
      }
      ... on HandSpecs {
        weightGrams
      }
    }
  }
}
fragment ToolCard on Tool {
  id
  name
  condition
  available
  specs {
    __typename
    summary
  }
  category {
    name
  }
  branch {
    name
  }
}

cdf90a4ce7adb67a675368a9fe37acf674d5a655:
mutation BorrowTool($input: BorrowInput!) {
  borrowTool(input: $input) {
    __typename
    ... on Borrowed {
      loan {
        id
        dueAt
        status
        tool {
          id
          name
          available
        }
      }
    }
    ... on Problem {
      message
    }
    ... on ToolUnavailable {
      expectedBack
    }
    ... on LoanLimitReached {
      limit
    }
    ... on InvalidInput {
      field
    }
  }
}

fc720a8da8f6fb4d32bc16e1f45bd4dd988902fc:
query Search($text: String!, $first: Int! = 8) {
  search(text: $text, first: $first) {
    __typename
    ... on Tool {
      id
      name
      available
    }
    ... on Category {
      id
      name
      toolCount
    }
    ... on Branch {
      id
      name
      address
    }
  }
}
